    public static UiBadgePaint Resolve(UiBadgeColorScheme scheme,UiBadgeAppearance appearance,UiBadgeColor color)
    {
        if((uint)appearance>3||(uint)color>7)throw new ArgumentOutOfRangeException(nameof(appearance));
        var palette=scheme switch {UiBadgeColorScheme.Light=>light,UiBadgeColorScheme.Dark=>dark,_=>throw new ArgumentOutOfRangeException(nameof(scheme))};
        return palette[(int)appearance*8+(int)color];
    }
